// Extract action from topic: umh/v1/smc/vienna/_work_order/<action>
var parts = msg.topic.split('/');
var action = parts[parts.length - 1] || 'unknown';

// Set color based on action
var color = 'grey';
if (action === 'create') color = 'green';
else if (action === 'update') color = 'blue';
else if (action === 'duplicate') color = 'yellow';
else if (action === 'process') color = 'grey';

var orderNr = '';
if (typeof msg.payload === 'object' && msg.payload !== null) {
    orderNr = msg.payload.order_nr || msg.payload.OrderNr || '';
}

node.status({fill: color, shape: 'dot', text: action.toUpperCase() + ': ' + orderNr});

msg.payload = {
    actie: action.toUpperCase(),
    order_nr: orderNr,
    data: msg.payload,
    topic: msg.topic,
    timestamp: new Date().toISOString()
};

return msg;

